// src/constants/paymentStatus.ts
export enum PaymentStatus {
  Pending = 0,
  Completed = 1,
  Duplicate = 2,
  FailedValidation = 3,
  Cancelled = 4,
  Refunded = 5,
  Error = 6
}

export const paymentStatusText: Record<PaymentStatus, string> = {
  [PaymentStatus.Pending]: 'รอการตรวจสอบหรือบันทึก',
  [PaymentStatus.Completed]: 'บันทึกเรียบร้อยแล้ว',
  [PaymentStatus.Duplicate]: 'พบว่าซ้ำกับรายการที่มีอยู่',
  [PaymentStatus.FailedValidation]: 'ไม่ผ่านการตรวจสอบ เช่น ข้อมูลไม่ถูกต้อง',
  [PaymentStatus.Cancelled]: 'ยกเลิกรายการ',
  [PaymentStatus.Refunded]: 'คืนเงินให้ผู้ชำระ',
  [PaymentStatus.Error]: 'เกิดข้อผิดพลาดในการประมวลผล'
};

export const paymentStatusColor: Record<PaymentStatus, 'default' | 'primary' | 'success' | 'warning' | 'error'> = {
  [PaymentStatus.Pending]: 'warning',
  [PaymentStatus.Completed]: 'success',
  [PaymentStatus.Duplicate]: 'primary',
  [PaymentStatus.FailedValidation]: 'error',
  [PaymentStatus.Cancelled]: 'default',
  [PaymentStatus.Refunded]: 'primary',
  [PaymentStatus.Error]: 'error'
};
